export function generate(kind='flowing',seed=1){const random=rng(seed);if(kind==='oval')return Array.from({length:12},(_,i)=>{let a=i/12*Math.PI*2;return{x:.5+Math.cos(a)*.4,y:.5+Math.sin(a)*.25}});let n=kind==='technical'?16:kind==='kart'?12:10;return Array.from({length:n},(_,i)=>{let a=i/n*Math.PI*2;let r=(kind==='technical'?.22:.29)+random()*.14;return{x:.5+Math.cos(a)*r,y:.5+Math.sin(a)*r*.86}})}
export function simplify(points,min=.015){let out=[];for(let p of points){if(!out.length||Math.hypot(p.x-out.at(-1).x,p.y-out.at(-1).y)>min)out.push(p)}if(out.length>3&&Math.hypot(out[0].x-out.at(-1).x,out[0].y-out.at(-1).y)<min*2)out.pop();return out.slice(0,100)}
export function nearest(samples,x,z){let best=Infinity,index=0;for(let i=0;i<samples.length;i++){let p=samples[i],d=(p.x-x)**2+(p.z-z)**2;if(d<best){best=d;index=i}}return{index,distance:Math.sqrt(best),point:samples[index]}}
export function advanceCheckpoints(state,index,n,onRoad,closed=true){const q=Math.floor(index/n*24);if(onRoad&&q===state.nextCheckpoint){state.nextCheckpoint++;}if(!closed&&onRoad&&state.nextCheckpoint===24&&index>=n-3){state.nextCheckpoint=1;state.lastIndex=index;return true}if(closed&&onRoad&&state.nextCheckpoint===24&&index<n*.04&&state.lastIndex>n*.9){state.nextCheckpoint=1;state.lastIndex=index;return true}state.lastIndex=index;return false}
